real_t algorithm_histogram(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const std::size_t n = 256;
    const std::size_t m = 256;

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        std::size_t i = 0;
        while (i < n) {
            std::size_t vl = __riscv_vsetvl_e64m1(n - i);
            vfloat64m1_t vz = __riscv_vfmv_v_f_f64m1(0.0, vl);
            __riscv_vse64_v_f64m1(reinterpret_cast<double*>(x + i), vz, vl);
            i += vl;
        }

        for (std::size_t i = 0; i < m; ++i) {
            x[idx_list[i]] += 1.0;
        }

        dummy(x, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

