static inline void algorithm_memset(struct args_t *func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const std::size_t n = static_cast<std::size_t>(LEN_1D);
    const std::size_t vlmax = __riscv_vsetvlmax_e64m1();

    real_t val = 1.42;

    for (int nl = 0; nl < iterations; ++nl) {
        std::size_t i = 0;
        while (i < n) {
            std::size_t vl = vlmax;
            if (vl > (n - i)) vl = n - i;

            vfloat64m1_t vv = __riscv_vfmv_v_f_f64m1(val, vl);
            __riscv_vse64_v_f64m1(reinterpret_cast<double *>(x + i), vv, vl);

            i += vl;
        }

        dummy(x, NULL, NULL, NULL, NULL, val);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

