static inline real_t algorithm_reduce_sum(struct args_t *func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;
    const std::size_t n = static_cast<std::size_t>(LEN_1D);

    for (int nl = 0; nl < iterations; ++nl) {
        real_t s = 0.0;

        std::size_t i = 0;
        while (i < n) {
            size_t vl = __riscv_vsetvl_e32m8(n - i);
            vfloat32m8_t vx = __riscv_vle32_v_f32m8(reinterpret_cast<const float *>(x + i), vl);
            vfloat32m8_t vsum = __riscv_vfredosum_vf_f32m8(vx, __riscv_vfmv_v_f_f32m8(0.0f, vl), vl);
            s += __riscv_vfmv_f_s_f32m8_f32(vsum);
            i += vl;
        }

        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }

    y[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

