real_t algorithm_scan(struct args_t * func_args)
{
    initialise_arrays(__func__);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        real_t scan_var = 0.0;
        Index_type i = 0;

        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e64m1(static_cast<size_t>(LEN_1D - i));

            vfloat64m1_t vx = __riscv_vle64_v_f64m1(x + i, vl);
            vfloat64m1_t vy = __riscv_vfmv_v_f_f64m1(scan_var, vl);

            __riscv_vse64_v_f64m1(y + i, vy, vl);

            vfloat64m1_t vsum = __riscv_vfredosum_vs_f64m1_f64m1(vx, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
            scan_var = __riscv_vfmv_f_s_f64m1_f64(vsum);

            i += static_cast<Index_type>(vl);
        }

        dummy(x, y, NULL, NULL, NULL, scan_var);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

