real_t apps_fir(struct args_t *func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const Index_type coefflen = APPS_COEFFLEN;
    const Index_type n1d = APPS_N1D;

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < n1d; ++i) {
            real_t s = 0.0f;
            Index_type j = 0;

            for (; j + 7 < coefflen; j += 8) {
                s += apps_coeff[j] * apps_in[i + j];
                s += apps_coeff[j + 1] * apps_in[i + j + 1];
                s += apps_coeff[j + 2] * apps_in[i + j + 2];
                s += apps_coeff[j + 3] * apps_in[i + j + 3];
                s += apps_coeff[j + 4] * apps_in[i + j + 4];
                s += apps_coeff[j + 5] * apps_in[i + j + 5];
                s += apps_coeff[j + 6] * apps_in[i + j + 6];
                s += apps_coeff[j + 7] * apps_in[i + j + 7];
            }
            for (; j < coefflen; ++j) {
                s += apps_coeff[j] * apps_in[i + j];
            }
            apps_out[i] = s;
        }
        dummy(apps_out, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

