static inline void apps_ltimes_noview(struct args_t *func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const Index_type num_d = LTIMES_NUM_D;
    const Index_type num_m = LTIMES_NUM_M;
    const Index_type num_g = LTIMES_NUM_G;
    const Index_type num_z = LTIMES_NUM_Z;

    for (int nl = 0; nl < iterations; ++nl) {
        for (Index_type z = 0; z < num_z; ++z) {
            const Index_type z_off = z * num_m * num_g;
            for (Index_type g = 0; g < num_g; ++g) {
                const Index_type g_off = g * num_d + z_off;
                for (Index_type m = 0; m < num_m; ++m) {
                    const Index_type base = m + g_off;
                    const Index_type dd = 0;

                    size_t vl = __riscv_vsetvl_e64m1(static_cast<size_t>(num_d));
                    vfloat64m1_t acc = __riscv_vfmv_v_f_f64m1(0.0, vl);

                    for (Index_type dd_local = 0; dd_local < num_d; ++dd_local) {
                        const double elld = lt_elldat[dd_local + m * num_d];
                        const double psid = lt_psidat[dd_local + g * num_d + z * num_d * num_g];
                        acc = __riscv_vfadd_vv_f64m1(acc, __riscv_vfmul_vf_f64m1(__riscv_vfmv_v_f_f64m1(elld, vl), __riscv_vfmv_v_f_f64m1(psid, vl), vl), vl);
                    }

                    __riscv_vse64_v_f64m1(reinterpret_cast<double *>(lt_phidat + base), acc, vl);
                }
            }
        }

        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

