        __riscv_vse32_v_f32m8(dst + i, v, vl);
        i += vl;
    }
}

real_t apps_nodal_accumulation_3d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const size_t n = APPS_N1D;
    const real_t c = 0.125f;

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        size_t i = 0;
        while (i < n) {
            size_t vl = __riscv_vsetvl_e32m8(n - i);

            vfloat32m8_t vvol = __riscv_vle32_v_f32m8(apps_vol + i, vl);
            vfloat32m8_t vval = __riscv_vfmul_vf_f32m8(vvol, c, vl);

            __riscv_vse32_v_f32m8(apps_x0 + i, vval, vl);
            __riscv_vse32_v_f32m8(apps_x1 + i, vval, vl);
            __riscv_vse32_v_f32m8(apps_x2 + i, vval, vl);
            __riscv_vse32_v_f32m8(apps_x3 + i, vval, vl);
            __riscv_vse32_v_f32m8(apps_x4 + i, vval, vl);
            __riscv_vse32_v_f32m8(apps_x5 + i, vval, vl);
            __riscv_vse32_v_f32m8(apps_x6 + i, vval, vl);
            __riscv_vse32_v_f32m8(apps_x7 + i, vval, vl);

            i += vl;
        }

        dummy(apps_x0, apps_x7, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

