real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t cls = 1.0f;
    const real_t p_cut = 1.0e-7f;
    const real_t pmin = 0.0f;
    const real_t eosvmax = 1.0e9f;

    const int nl_max = iterations / 4 + 1;

    for (int nl = 0; nl < nl_max; ++nl) {
        int i = 0;
        while (i < APPS_N1D) {
            size_t vl = __riscv_vsetvl_e32m1(static_cast<size_t>(APPS_N1D - i));

            vfloat32m1_t vcomp = __riscv_vle32_v_f32m1(apps_compression + i, vl);
            vfloat32m1_t vone = __riscv_vfmv_v_f_f32m1(1.0f, vl);
            vfloat32m1_t vcls = __riscv_vfmv_v_f_f32m1(cls, vl);
            vfloat32m1_t vbc = __riscv_vfmacc_vv_f32m1(vcomp, vone, vcls, vl);

            __riscv_vse32_v_f32m1(apps_bvc + i, vbc, vl);
            i += static_cast<int>(vl);
        }

        i = 0;
        while (i < APPS_N1D) {
            size_t vl = __riscv_vsetvl_e32m1(static_cast<size_t>(APPS_N1D - i));

            vfloat32m1_t vbvc = __riscv_vle32_v_f32m1(apps_bvc + i, vl);
            vfloat32m1_t ve_old = __riscv_vle32_v_f32m1(apps_e_old + i, vl);
            vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(vbvc, ve_old, vl);

            vfloat32m1_t vabs = __riscv_vfabs_v_f32m1(vprod, vl);
            vbool32_t mlt = __riscv_vmslt_vf_f32m1_b32(vabs, p_cut, vl);
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
            vfloat32m1_t vres = __riscv_vmerge_vvm_f32m1(vprod, vzero, mlt, vl);

