    gettimeofday(&func_args->t1, NULL);

    const real_t x0 = 0.0, h = 1.0 / (real_t)LEN_1D;
    const real_t yp = 1.0, ypoint = 1.0;
    const real_t dy = (ypoint - yp);
    const real_t dy2 = dy * dy;
    const real_t inv_h = 1.0 / h;

    real_t acc = 0.0;

    for (int nl = 0; nl < iterations; ++nl) {
        real_t sumx = 0.0;

        int i = 0;
        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e64m1((size_t)(LEN_1D - i));

            vfloat64m1_t vidx = __riscv_vfmv_v_f_f64m1((double)i, vl);
            vfloat64m1_t vxv = __riscv_vfmv_v_f_f64m1((double)x0, vl);
            vxv = __riscv_vfmacc_vf_f64m1(vxv, (double)inv_h, vidx, vl);

            vfloat64m1_t vden = __riscv_vfsub_vv_f64m1(vxv, __riscv_vfmv_v_f_f64m1(0.5, vl), vl);
            vden = __riscv_vfmul_vv_f64m1(vden, vden, vl);
            vden = __riscv_vfadd_vv_f64m1(vden, __riscv_vfmv_v_f_f64m1(dy2, vl), vl);

            vfloat64m1_t vone = __riscv_vfmv_v_f_f64m1(1.0, vl);
            vfloat64m1_t vsqrt = __riscv_vfsqrt_vv_f64m1(vden, vl);
            vsqrt = __riscv_vfadd_vv_f64m1(vsqrt, vone, vl);

            vfloat64m1_t vrecip = __riscv_vfrec7_v_f64m1(vsqrt, vl);

            vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, vl);
            vsum = __riscv_vfredosum_vs_f64m1_f64m1(vrecip, vsum, vl);

            double out[1];
            __riscv_vse64_v_f64m1(out, vsum, vl);
            sumx += (real_t)out[0];

            i += (int)vl;
        }

        acc += sumx;
        dummy(NULL, NULL, NULL, NULL, NULL, sumx);
    }

    x[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

